package accounts

import (
	"strings"
	"sync/atomic"
	"testing"

	"github.com/goccy/go-json"
	"github.com/stretchr/testify/require"
)

func TestValidateTxFees(t *testing.T) {
	t.Skip("TODO: reenable when FE ready")
	a := accounts{
		bscFees: new(atomic.Pointer[Fee]),
		cfg:     &config{TransactionValidationFeeSlippage: 0.05},
	}
	a.bscFees.Store(&Fee{MaxFeePerGas: "100", MaxPriorityFeePerGas: "100"})
	t.Run("tx gets rejected when fee is higher than expected", func(t *testing.T) {
		txWithExceedingFeesData := `{
          "kind": "UserOperations",
          "maxFeePerGas": "110",
          "userOperations": [
            {
              "to": "0x4Ab1807ff59a391503b0C8E28D2647bd9A7ecdA1",
              "data": ""
            },
            {
              "to": "0x4Ab1807ff59a391503b0C8E28D2647bd9A7ecdA1",
              "data": ""
            }
          ],
          "feeSponsorId": "fs-01jg7-2dotc-esmbtjcn9udvpvk8"
        }`
		var txWithExceedingFees TransactionPayload
		require.NoError(t, json.Unmarshal([]byte(txWithExceedingFeesData), &txWithExceedingFees))
		require.Error(t, a.validateTxGas(&txWithExceedingFees), ErrValidationFailed)
	})
	t.Run("tx gets passed when fee is below threshold or fee sponsor id is not set", func(t *testing.T) {
		txWithLowFeesData := `{
          "kind": "UserOperations",
          "maxFeePerGas": "99",
          "userOperations": [
            {
              "to": "0x4Ab1807ff59a391503b0C8E28D2647bd9A7ecdA1",
              "data": ""
            },
            {
              "to": "0x4Ab1807ff59a391503b0C8E28D2647bd9A7ecdA1",
              "data": ""
            }
          ],
          "feeSponsorId": "fs-01jg7-2dotc-esmbtjcn9udvpvk8"
        }`
		var txWithLowFees TransactionPayload
		require.NoError(t, json.Unmarshal([]byte(txWithLowFeesData), &txWithLowFees))
		require.NoError(t, a.validateTxGas(&txWithLowFees))
		var txNoFees TransactionPayload
		require.NoError(t, json.Unmarshal([]byte(strings.ReplaceAll(txWithLowFeesData, "\"maxFeePerGas\": \"99\",", "")), &txNoFees))
		require.NoError(t, a.validateTxGas(&txNoFees))
		require.NoError(t, json.Unmarshal([]byte(strings.ReplaceAll(txWithLowFeesData, ",\n          \"feeSponsorId\": \"fs-01jg7-2dotc-esmbtjcn9udvpvk8\"", "")), &txNoFees))
		require.NoError(t, a.validateTxGas(&txNoFees))
	})
}
